<script setup lang="ts">
// 打开页面分布：统计页「打开教练时所在页面」区块的专用展示（个人页与管理页共用）。
//
// 比通用分布列表多两件事：
//   1. 每行除了中文页面名，还给出路由 name 与最常见的真实访问路径（route.path + 查询参数名）——
//      只显示「题目详情」回答不了「用户具体在哪道题 / 哪次提交上问起」；
//   2. 点行弹出详情：路由模板（取自当前前端路由表）、所属 tab、登录要求，以及该页面下的路径分布。
//
// 数据来源两处、各自都可能缺：路径来自统计接口（旧数据没有 entry_path），
// 路由模板来自前端路由表（页面可能已下线或改名）。缺什么就说明什么，不编造、不隐藏。

import { computed, ref } from "vue";
import { useRouter } from "vue-router";
import { getTabConfig } from "@/config/tab-config";
import { useBreakpoint } from "@/composables/useBreakpoint";
import {
  buildEntryPageSecondaryLabels,
  fmtCount,
  getEntryPagePathCount,
  getEntryPagePaths,
  UNKNOWN_ENTRY_PATH,
  UNKNOWN_ENTRY_ROUTE,
} from "@/views/ai/ai-stats-common";
import type { AiStatsBucket, AiStatsEntryPage } from "@/types/ai-stats";
import AiStatsDistList from "@/components/ai/AiStatsDistList.vue";

const props = defineProps<{
  rows: AiStatsEntryPage[];
  /** 路由 name → 中文页面名 */
  labels?: Record<string, string>;
  emptyText?: string;
}>();

const router = useRouter();
const { isMobile } = useBreakpoint();

const pageName = (key: string): string => (key ? props.labels?.[key] ?? key : UNKNOWN_ENTRY_ROUTE);

/** 行副标题：路由 name + 最常见的真实路径（规则在 ai-stats-common，个人页与管理页共用一份） */
const secondaryLabels = computed(() => buildEntryPageSecondaryLabels(props.rows));

// ── 详情弹窗 ──

const detailVisible = ref(false);
const activeRow = ref<AiStatsEntryPage | null>(null);

/** 点行：按 key 回查完整行（分布列表的 select 只透出通用桶字段，路径明细不在其中） */
const openDetail = (row: AiStatsBucket) => {
  activeRow.value = props.rows.find((item) => item.key === row.key) ?? null;
  detailVisible.value = true;
};

const activePaths = computed(() => (activeRow.value ? getEntryPagePaths(activeRow.value) : []));
const activePathCount = computed(() => (activeRow.value ? getEntryPagePathCount(activeRow.value) : 0));

/** 是否出现带查询参数的路径：出现时才解释「只记参数名不记取值」（见 BuildAiCoachEntryPath） */
const hasQueryKeys = computed(() => activePaths.value.some((path) => path.key.includes("?")));

/**
 * 路由模板与元信息：直接查路由表，不用 router.resolve——
 * 这些路由大多带必填参数（如 /problem/:problemKey+），resolve 会因缺参数打告警，
 * 而这里要的恰恰是「模板」本身，不是某个具体地址。
 */
const routeRecord = computed(() => {
  const key = activeRow.value?.key;
  if (!key) {
    return null;
  }
  return router.getRoutes().find((record) => record.name === key) ?? null;
});

const routePath = computed(() => routeRecord.value?.path ?? "");

const tabTitle = computed(() => {
  const tab = routeRecord.value?.meta?.tab;
  if (typeof tab !== "string") {
    return "";
  }
  return getTabConfig(tab)?.title ?? tab;
});

const needLogin = computed(() => routeRecord.value?.meta?.needLogin === true);
</script>

<template>
  <div class="entry-page-dist">
    <p v-if="rows.length > 0" class="entry-page-tip">点击任意一行，查看该页面下用户实际问起的具体路径。</p>
    <AiStatsDistList
      title=""
      :rows="rows"
      metric="conversations"
      :labels="labels"
      :secondary="secondaryLabels"
      clickable
      :empty-text="emptyText"
      @select="openDetail"
    />

    <!-- 详情：路由信息 + 该页面下的真实访问路径 -->
    <t-dialog
      v-model:visible="detailVisible"
      :header="activeRow ? `打开页面详情 · ${pageName(activeRow.key)}` : '打开页面详情'"
      :width="isMobile ? '90%' : '560px'"
      :footer="false"
    >
      <div v-if="activeRow" class="entry-detail">
        <div class="entry-detail-row">
          <span class="entry-detail-label">路由 name</span>
          <code class="entry-detail-value">{{ activeRow.key || UNKNOWN_ENTRY_ROUTE }}</code>
        </div>
        <div class="entry-detail-row">
          <span class="entry-detail-label">路由模板</span>
          <code v-if="routePath" class="entry-detail-value">{{ routePath }}</code>
          <span v-else class="entry-detail-value is-muted">当前路由表中已无此页面（可能已下线或改名）</span>
        </div>
        <div class="entry-detail-row">
          <span class="entry-detail-label">所属 tab</span>
          <span class="entry-detail-value">{{ tabTitle || "—" }}</span>
        </div>
        <div class="entry-detail-row">
          <span class="entry-detail-label">需要登录</span>
          <span class="entry-detail-value">{{ needLogin ? "是" : "否" }}</span>
        </div>
        <div class="entry-detail-row">
          <span class="entry-detail-label">汇总</span>
          <span class="entry-detail-value">
            {{ activeRow.conversations }} 会话 · {{ fmtCount(activeRow.messages) }} 消息 ·
            {{ fmtCount(activeRow.total_tokens) }} tokens
          </span>
        </div>

        <div class="entry-detail-title">具体访问路径（{{ activePathCount }} 条）</div>
        <p v-if="hasQueryKeys" class="entry-detail-note">
          路径中 <code>?</code> 之后是查询参数名：统计只记录参数名、不记录取值，避免把用户输入带进统计。
        </p>
        <div class="entry-path-list">
          <div v-for="path in activePaths" :key="path.key" class="entry-path-row">
            <code class="entry-path-key" :class="{ 'is-muted': !path.key }" :title="path.key || UNKNOWN_ENTRY_PATH">
              {{ path.key || UNKNOWN_ENTRY_PATH }}
            </code>
            <span class="entry-path-meta">
              {{ path.conversations }} 会话 · {{ fmtCount(path.messages) }} 消息 ·
              {{ fmtCount(path.total_tokens) }} tokens
            </span>
          </div>
        </div>
        <p v-if="activePaths.length === 0" class="entry-detail-note">这个页面还没有可展示的具体路径记录。</p>
        <p v-else-if="activePathCount > activePaths.length" class="entry-detail-note">
          仅展示会话数最多的 {{ activePaths.length }} 条，共 {{ activePathCount }} 条。
        </p>
      </div>
    </t-dialog>
  </div>
</template>

