// AI 教练统计接口：个人 GET /ai/stats 与全站 GET /ai/admin/stats。
//
// 两者都是普通 JSON（非流式），走项目既有的 axios 封装；
// 后端对应的 controller 方法在 web/controller/ai.go 的 GetStats / GetAdminStats，
// 门禁：个人 = 登录即可，全站 = i-manage-problem（与 AI 审阅后台一致）。

import httpRequest from "@/apis/axios-api";

/** 我的教练统计（仅本人聚合数据） */
export function GetAiStats() {
  return httpRequest({
    url: "/ai/stats",
    method: "get",
  });
}

/** 全站教练统计（管理视角，缺权限返回 100122） */
export function GetAiAdminStats() {
  return httpRequest({
    url: "/ai/admin/stats",
    method: "get",
  });
}
